function persistentDeviceKey(){const storageKey="flight-ia-device-key";let value=localStorage.getItem(storageKey);if(value)return value;value=globalThis.crypto?.randomUUID?.()??`${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;localStorage.setItem(storageKey,value);return value;}
function rowToPassage(row:PassageRow):Passage { return {id:row.id,prefix:row.prefix,model:row.model,base:row.base,date:row.date,openedAt:row.opened_at,updatedAt:row.updated_at,createdBy:row.created_by,checks:row.checks,actions:row.actions,discrepancyDetails:row.discrepancy_details,oilQuantity:row.oil_quantity,oilAdditions:row.oil_additions??undefined,notes:row.notes,revision:row.revision}; }
function passageToRow(item:Passage):PassageRow { return {id:item.id,prefix:item.prefix,model:item.model,base:item.base,date:item.date,opened_at:item.openedAt,updated_at:item.updatedAt,created_by:item.createdBy,checks:item.checks,actions:item.actions,discrepancy_details:item.discrepancyDetails,oil_quantity:item.oilQuantity??"",oil_additions:item.oilAdditions??null,notes:item.notes,revision:item.revision??0}; }
function passagePatchToRow(patch:Partial<Passage>):Partial<PassageRow> { const row:Partial<PassageRow>={}; if(patch.prefix!==undefined)row.prefix=patch.prefix;if(patch.model!==undefined)row.model=patch.model;if(patch.base!==undefined)row.base=patch.base;if(patch.date!==undefined)row.date=patch.date;if(patch.openedAt!==undefined)row.opened_at=patch.openedAt;if(patch.updatedAt!==undefined)row.updated_at=patch.updatedAt;if(patch.createdBy!==undefined)row.created_by=patch.createdBy;if(patch.checks!==undefined)row.checks=patch.checks;if(patch.actions!==undefined)row.actions=patch.actions;if(patch.discrepancyDetails!==undefined)row.discrepancy_details=patch.discrepancyDetails;if(patch.oilQuantity!==undefined)row.oil_quantity=patch.oilQuantity;if(patch.oilAdditions!==undefined)row.oil_additions=patch.oilAdditions;if(patch.notes!==undefined)row.notes=patch.notes;if(patch.revision!==undefined)row.revision=patch.revision;return row; }

function arrivalTime(flight: Pick<Flight,"departure"|"duration"|"actualEngineStart">) {
  const [hour,minute]=(flight.actualEngineStart??flight.departure).split(":").map(Number);
  const total=hour*60+minute+Math.round(flight.duration*60);
  return `${String(Math.floor(total/60)%24).padStart(2,"0")}:${String(total%60).padStart(2,"0")}`;
}

function flightStatus(flight: Flight,user: string) {
  if(flight.planningStatus==="planned")return{key:"planned",label:"Programado",color:"#f97316"};
  if(flight.cancelled) return { key: "cancelled",label: "Voo cancelado",color: "#dc2626" };
  if(flight.shutdown==="ok"||flight.actualShutdown) return { key: flight.returned?"returned":"finished",label: flight.returned?"Retorno encerrado":"Voo encerrado",color: flight.returned?"#ea580c":"#94a3b8" };
  if(flight.engineStart==="ok"||flight.actualEngineStart) return { key: "flying",label: flight.returned?"Em voo · retorno":"Em voo",color: "#22a06b" };
  if(flight.planningStatus==="confirmed")return{key:"confirmed",label:"Voo confirmado",color:"#2383e2"};
  if((flight.acknowledged[user]??0)>=flight.revision) return { key: "aware",label: "Ciente",color: "#2383e2" };
  return { key: "attention",label: "Aguardando ciência",color: "#f2b824" };
}

function todayLocal() { const now=new Date(); return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-${String(now.getDate()).padStart(2,"0")}`; }
function durationToClock(duration:number) { const total=Math.max(0,Math.round(duration*60)); return `${String(Math.floor(total/60)).padStart(2,"0")}:${String(total%60).padStart(2,"0")}`; }
function clockToDuration(value:string) { const [hours,minutes]=value.split(":").map(Number); return (hours*60+minutes)/60; }
function timelineCategory(flight:Flight):FlightView { if(flight.planningStatus==="planned")return "planned";if(flight.cancelled)return "cancelled"; if(flight.shutdown==="ok"||flight.actualShutdown)return flight.returned?"returned":"finished"; return flight.engineStart==="ok"||Boolean(flight.actualEngineStart)?"flying":"launched"; }
function timelineTime(flight:Flight) { const category=timelineCategory(flight); const explicit=category==="returned"?flight.completedAt??flight.returnedAt:category==="cancelled"?flight.cancelledAt:category==="finished"?flight.completedAt:undefined; const latest=flight.history?.at(-1)?.at; return Date.parse(explicit??latest??`${flight.date}T${flight.departure}:00-03:00`); }
function nextOperationalActionTime(flight:Flight) { const category=timelineCategory(flight); const time=category==="flying"?flight.actualEngineStart??flight.departure:flight.departure; const start=Date.parse(`${flight.date}T${time}:00-03:00`); if(!Number.isFinite(start))return Number.POSITIVE_INFINITY; return category==="flying"?start+Math.round(flight.duration*60)*60000:start; }
function fieldChanged(flight:Flight,user:string,field:string) { return (flight.fieldRevisions?.[field]??0)>(flight.acknowledged[user]??0); }
function urlBase64ToUint8Array(value:string) { const padding="=".repeat((4-value.length%4)%4); const base64=(value+padding).replace(/-/g,"+").replace(/_/g,"/"); return Uint8Array.from(atob(base64),(character)=>character.charCodeAt(0)); }
function changedPatch<T>(before:T,after:T):Partial<T> { const patch:Record<string,unknown>={}; for(const key of Object.keys(after as object)) { const previous=(before as Record<string,unknown>)[key]; const next=(after as Record<string,unknown>)[key]; if(JSON.stringify(previous)!==JSON.stringify(next)) patch[key]=next; } return patch as Partial<T>; }
async function prepareAvatar(file:File){if(!file.type.startsWith("image/"))throw new Error("Selecione um arquivo de imagem.");const bitmap=await createImageBitmap(file);const side=Math.min(bitmap.width,bitmap.height);const canvas=document.createElement("canvas");canvas.width=256;canvas.height=256;canvas.getContext("2d")!.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,256,256);bitmap.close();const data=canvas.toDataURL("image/jpeg",.82);if(data.length>350000)throw new Error("Não foi possível reduzir esta imagem. Escolha outra foto.");return data;}

